// Generated from NotoSansCJKjp-Regular.otf (OFL-1.1) using pyftsubset.
// The subset is built from the app's current content and PDF labels.
const FONT_BASE64 = '';

let cachedBytes: Uint8Array | null = null;

export function getNotoSansCjkJpSubsetBytes(): Uint8Array {
  if (cachedBytes) {
    return cachedBytes;
  }

  const raw = atob(FONT_BASE64);
  const bytes = new Uint8Array(raw.length);
  for (let index = 0; index < raw.length; index += 1) {
    bytes[index] = raw.charCodeAt(index);
  }
  cachedBytes = bytes;
  return bytes;
}
